import importlib.util, struct, os, sys
# bytecode header (py3.12): magic(4) flags(4) mtime(4) size(4)
def check(pyc):
    py = os.path.splitext(pyc)[0] + ".py"
    if not os.path.exists(py): return None
    with open(pyc,"rb") as f: hdr = f.read(16)
    if len(hdr) < 16: return None
    magic, flags, mtime, size = struct.unpack("<IIII", hdr[:16])
    st = os.stat(py)
    return dict(py=py, pyc_mtime=mtime, py_mtime=int(st.st_mtime), pyc_size=size, py_size=st.st_size,
                mismatch=(mtime != int(st.st_mtime) or size != st.st_size))
base="/workspace/verl"
res=[]
for root,dirs,files in os.walk(base):
    if "__pycache__" in root:
        for fn in files:
            if fn.endswith(".pyc"):
                r = check(os.path.join(root,fn))
                if r: res.append(r)
print(f"checked {len(res)} pyc files")
bad=[r for r in res if r["mismatch"]]
